  `stock_consumed` tinyint(1) DEFAULT NULL COMMENT 'TRUE/FALSE/NULL (3 états possibles legacy)',
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Clé d''idempotence si fournie (UNIQUE, NULL multiples autorisés)',
  `legacy_created_at` datetime DEFAULT NULL,
