(1, 'prod-poulet-bowl', 16, 'cat-healthy', 'BEBBA Chicken Power Bowl', 'Filet de poulet mariné grillé minute, riz basmati complet, brocolis, courgettes grillées, avocat et sauce signature légère.', 14.50, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 520, 42.00, 48.00, 14.00, 1, 1, 1, 1, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(2, 'prod-poulet-grille', 17, 'cat-grillades', 'Assiette Grillade Poulet Mariné', 'Poitrine de poulet fermier grillée à la flamme avec épices tunisiennes douces, accompagnée de patates douces rôties et légumes sautés.', 16.00, 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=800&q=80', 560, 48.00, 38.00, 16.00, 1, 1, 1, 1, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(3, 'prod-boeuf-grillade', 17, 'cat-grillades', 'Assiette Bœuf Grillé & Romarin', 'Pavé de bœuf maigre tendre saisi sur le grill, légumes croquants rôties au four et sauce signature aux herbes.', 19.50, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', 590, 50.00, 32.00, 18.00, 1, 1, 1, 0, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(4, 'prod-quinoa-green-bowl', 16, 'cat-healthy', 'Quinoa Superfood & Halloumi Bowl', 'Quinoa royal, tranches d’halloumi grillé, avocat frais, œuf bio poché, brocolis vapeur et vinaigrette légère au citron.', 15.50, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 490, 28.00, 42.00, 22.00, 1, 1, 1, 0, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(5, 'prod-salade-fraicheur', 18, 'cat-salades', 'Grande Salade BEBBA Croustillante', 'Mélange de jeunes pousses, concombre croquant, carottes râpées, tomates cerises, avocat, graines de courge et poulet effiloché tiède.', 13.00, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 380, 32.00, 20.00, 14.00, 1, 1, 1, 0, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(6, 'prod-jus-detox-vert', 19, 'cat-boissons', 'Jus Vert Détox Vitalité (350ml)', 'Pomme verte, concombre, épinards, menthe fraîche et touche de gingembre. Pressé à froid sans sucre.', 5.50, 'https://images.unsplash.com/photo-1613478223719-2ab802602423?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1613478223719-2ab802602423?auto=format&fit=crop&w=800&q=80', 110, 2.00, 24.00, 0.00, 1, 1, 1, 1, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(7, 'prod-jus-orange-carotte', 19, 'cat-boissons', 'Jus Boost Énergie Orange & Carotte (350ml)', 'Oranges douces de Tunisie pressées à la minute avec carottes fraîches et pointe de curcuma.', 5.00, 'https://images.unsplash.com/photo-1600271886742-f049cd451bba?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600271886742-f049cd451bba?auto=format&fit=crop&w=800&q=80', 125, 2.00, 28.00, 0.00, 1, 1, 1, 0, 0, 0, NULL, NULL, '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(8, 'prod-saumon-zen-bowl', 16, 'cat-healthy', 'Bowl Saumon Énergie & Avocat', 'Pavé de saumon frais poêlé, quinoa royal, dés d’avocat, graines de sésame grillées et légumes vapeur croquants.', 18.50, 'https://images.unsplash.com/photo-1546069901-d7790b4119d6?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1546069901-d7790b4119d6?auto=format&fit=crop&w=800&q=80', 550, 38.00, 36.00, 24.00, 1, 1, 1, 1, 3, 3, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(9, 'prod-bowl-vegetal-mediterraneen', 16, 'cat-healthy', 'Bowl Végétal Méditerranéen', 'Composition 100% végétale avec quinoa, légumes rôtis au four, avocat crémeux, graines de courge et herbes de Mornag.', 13.50, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', 420, 18.00, 52.00, 16.00, 1, 1, 1, 0, 4, 4, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(10, 'prod-mix-grill-fitness', 17, 'cat-grillades', 'Mix Grill BEBBA Fitness', 'Duo de poulet mariné et bœuf maigre grillé minute, légumes du soleil et riz complet basmati.', 22.00, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=800&q=80', 640, 58.00, 40.00, 18.00, 1, 1, 1, 1, 3, 3, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(11, 'prod-brochettes-dinde', 17, 'cat-grillades', 'Brochettes de Dinde aux Épices Douces', 'Brochettes de dinde fermière marinées au paprika doux et herbes fraîches, grillées au feu de bois.', 15.00, 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80', 480, 44.00, 35.00, 12.00, 1, 1, 1, 0, 4, 4, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(12, 'prod-menu-ptit-champion', 20, 'cat-enfants', 'Menu P\'tit Champion Poulet & Riz Doux', 'Émincé de filet de poulet grillé tendre, riz basmati parfumé, petits dés de carottes & courgettes et sauce douce.', 11.00, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', 380, 28.00, 42.00, 8.00, 1, 1, 1, 1, 1, 1, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(13, 'prod-mini-bowl-gourmet', 20, 'cat-enfants', 'Mini Bowl P\'tit Gourmet & Légumes Colorés', 'Petits cubes de poulet doré, patates douces au four croustillantes, dés d’avocat et sauce yaourt.', 10.50, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 350, 24.00, 36.00, 10.00, 1, 1, 1, 0, 2, 2, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(14, 'prod-batonnets-poulet-dore', 20, 'cat-enfants', 'P\'tits Bâtonnets de Poulet au Four', 'Bâtonnets de filet de poulet panés aux graines et cuits au four sans friture, accompagnés de riz doux.', 11.50, 'https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=800&q=80', 390, 30.00, 38.00, 9.00, 1, 1, 1, 0, 3, 3, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(15, 'prod-elixir-betterave', 21, 'cat-jus-detox', 'Élixir Détox Betterave & Gingembre (350ml)', 'Betterave rouge bio, pomme, jus de citron pressé et racine de gingembre frais pour stimuler l\'oxygénation.', 5.50, 'https://images.unsplash.com/photo-1556881286-fc6915169721?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1556881286-fc6915169721?auto=format&fit=crop&w=800&q=80', 115, 2.00, 26.00, 0.00, 1, 1, 1, 0, 3, 3, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(16, 'prod-eau-infusee', 21, 'cat-jus-detox', 'Eau Infusée Concombre Menthe Citron (500ml)', 'Eau minérale infusée à froid pendant 12h avec tranches de concombre frais, menthe du jardin et citron bio.', 3.50, 'https://images.unsplash.com/photo-1523362628745-0c100150b504?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1523362628745-0c100150b504?auto=format&fit=crop&w=800&q=80', 15, 0.00, 3.00, 0.00, 1, 1, 1, 0, 4, 4, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(17, 'prod-programme-30j-perte', 22, 'cat-regime-30j', 'Programme 30 Jours — Perte de Poids & Détox', 'Pack complet de 30 jours comprenant 2 repas sains quotidiens (midi + soir) et un jus détox par jour avec suivi nutritionnel.', 380.00, 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 1100, 85.00, 95.00, 30.00, 1, 1, 1, 1, 1, 1, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
(18, 'prod-programme-30j-masse', 22, 'cat-regime-30j', 'Programme 30 Jours — Prise de Masse Sèche', 'Formule sportive enrichie en protéines nobles (poulet, bœuf maigre, quinoa, patates douces) avec collations énergétiques.', 440.00, 'https://images.unsplash.com/photo-1547496502-affa22d38842?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1547496502-affa22d38842?auto=format&fit=crop&w=800&q=80', 1650, 140.00, 150.00, 42.00, 1, 1, 1, 0, 2, 2, '2026-09-01 08:54:57', '2026-09-01 08:54:57', '2026-09-20 04:20:01', '2026-09-20 04:20:01'),
